import {HARMONICS} from './voice-dsp.mjs';
import {PARTICLES} from './mouth-dsp.mjs';
class PlaneMorph extends AudioWorkletProcessor{
 constructor(options){super();this.target=options.processorOptions.model;this.pitch=this.target.pitch;this.voicing=this.target.voicing;this.amps=Float64Array.from(this.target.amplitudes);this.freq=Float64Array.from(this.target.frequencies);this.phase=0;this.fade=0;this.energy=.0324;this.gain=1;this.sin=new Float64Array(PARTICLES);this.cos=new Float64Array(PARTICLES);let seed=0x6d2b79f5;for(let v=0;v<PARTICLES;v++){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;const phase=(seed>>>0)/4294967296*Math.PI*2;this.sin[v]=Math.sin(phase);this.cos[v]=Math.cos(phase)}
 this.pitchSmooth=1-Math.exp(-1/(sampleRate*.055));this.voiceSmooth=1-Math.exp(-1/(sampleRate*.05));this.ampSmooth=1-Math.exp(-1/(sampleRate*.035));
 this.port.onmessage=e=>{const m=e.data.model;if(!m)return;
 // Prime a previously inaudible component before fading it in. Never glide
 // a new hiss up from the zero-frequency placeholder or erase a fading voice.
 if(this.voicing>.999&&m.voicing<.9999)this.freq.set(m.frequencies);
 if(this.voicing<.001&&m.voicing>.0001){this.pitch=m.pitch;this.amps.set(m.amplitudes)}this.target=m;};this.noise=new Float32Array(128)}
 process(inputs,outputs){const channels=outputs[0],out=channels[0],m=this.target;if(this.noise.length!==out.length)this.noise=new Float32Array(out.length);const noise=this.noise;noise.fill(0);
 if(m.voicing<.999999||this.voicing<.999999){const scale=.18*Math.sqrt(2/PARTICLES),frequencySmooth=1-Math.exp(-out.length/(sampleRate*.07));for(let v=0;v<PARTICLES;v++){if(m.voicing<.999999)this.freq[v]+=(m.frequencies[v]-this.freq[v])*frequencySmooth;const angle=2*Math.PI*Math.min(sampleRate*.46,Math.max(25,this.freq[v]))/sampleRate,dc=Math.cos(angle),ds=Math.sin(angle);let s=this.sin[v],c=this.cos[v];for(let j=0;j<out.length;j++){noise[j]+=s*scale;const next=s*dc+c*ds;c=c*dc-s*ds;s=next}const norm=1/Math.hypot(s,c);this.sin[v]=s*norm;this.cos[v]=c*norm}let energy=0;for(const v of noise)energy+=v*v;this.energy=.97*this.energy+.03*energy/out.length}
 for(let j=0;j<out.length;j++){if(m.voicing>.000001)this.pitch+=(m.pitch-this.pitch)*this.pitchSmooth;this.voicing+=(m.voicing-this.voicing)*this.voiceSmooth;this.phase=(this.phase+2*Math.PI*this.pitch/sampleRate)%(2*Math.PI);let tone=0;for(let h=1;h<=HARMONICS;h++){if(m.voicing>.000001)this.amps[h-1]+=(m.amplitudes[h-1]-this.amps[h-1])*this.ampSmooth;if(this.voicing>.000001&&h*this.pitch<sampleRate*.46)tone+=this.amps[h-1]*Math.sin(h*this.phase-Math.PI*h*(h-1)/HARMONICS)}this.gain+=(Math.min(2,.18/Math.sqrt(this.energy+1e-8))-this.gain)*.001;this.fade=Math.min(1,this.fade+1/(sampleRate*.04));out[j]=Math.tanh(tone*Math.sqrt(Math.max(0,this.voicing))+noise[j]*this.gain*Math.sqrt(Math.max(0,1-this.voicing)))*this.fade}for(let c=1;c<channels.length;c++)channels[c].set(out);return true}
}registerProcessor('plane-morph',PlaneMorph);
